fn find_smallest(s: &Vec<u32>) -> Option<u32> {
    if s.is_empty() {
        return None;
    }

    let mut smallest = s[0]; // Start with the first element as the smallest
    for &num in s.iter() {
        if num < smallest {
            smallest = num; // Update smallest if a smaller number is found
        }
    }

    Some(smallest) // Return the smallest number wrapped in Some
}